// CloudWatch Synthetics canary that exercises the ENTIRE checkout journey.
// Book ch. 8: a probe that only does GET / tests a fraction of what matters.
// Each step is reported separately so you can see which CUI broke.
const synthetics = require('Synthetics');
const log = require('SyntheticsLogger');
const https = require('https');

const BASE = process.env.BASE_URL || 'https://example.com';

function get(path, headers = {}) {
  return new Promise((resolve, reject) => {
    const req = https.get(BASE + path, { headers: { 'x-cuj': 'checkout', ...headers }, timeout: 5000 }, (res) => {
      let body = '';
      res.on('data', (d) => (body += d));
      res.on('end', () => resolve({ status: res.statusCode, body, version: res.headers['x-served-by-version'] }));
    });
    req.on('timeout', () => req.destroy(new Error('timeout')));
    req.on('error', reject);
  });
}

async function step(name, path, validate) {
  await synthetics.executeStep(name, async () => {
    const r = await get(path);
    log.info(`${name}: status=${r.status} version=${r.version}`);
    if (r.status !== 200) throw new Error(`${name} returned ${r.status}`);
    // "Successfully failing" check from the Maps case study: a 200 with an
    // empty/invalid payload is still a broken journey.
    if (validate && !validate(r.body)) throw new Error(`${name} returned an invalid payload`);
  });
}

exports.handler = async () => {
  await step('search', '/search?q=widget', (b) => b.length > 0);
  await step('add_to_cart', '/cart/add?sku=123');
  await step('checkout', '/checkout');
};
